use cf_orchestrator::{Ferry,FerryOptions,frozen_request};use serde::{Deserialize,Serialize};
#[derive(Clone,Debug,Serialize,Deserialize)]pub struct ModeResult{pub mode:String,pub selected:usize,pub tokens:u32,pub recalled:bool,pub evidence:bool,pub robust:bool,pub replayed_decisions:usize,pub objective:f64}
pub fn evaluate_modes()->Vec<ModeResult>{let modes=[("combined",FerryOptions::default()),("no-ruvector",FerryOptions{ruvector:false,..FerryOptions::default()}),("no-rvf",FerryOptions{rvf:false,..FerryOptions::default()}),("no-tiktoken",FerryOptions{tiktoken:false,..FerryOptions::default()}),("no-conformal",FerryOptions{conformal:false,..FerryOptions::default()}),("enterprise-only",FerryOptions{ruvector:false,rvf:false,tiktoken:true,conformal:false}),("ruvnet-only",FerryOptions{ruvector:true,rvf:true,tiktoken:false,conformal:false})];modes.into_iter().map(|(name,options)|{let d=tempfile::tempdir().unwrap();let o=Ferry::new(d.path().join("db").to_str().unwrap(),options).execute(&frozen_request()).unwrap();let objective=o.capsule.events.iter().map(|e|e.importance).sum::<f64>()*10.0-f64::from(o.capsule.used_tokens)/20.0+if o.telemetry.evidence_verified{1.0}else{0.0}+if o.robust{1.0}else{0.0};ModeResult{mode:name.into(),selected:o.telemetry.selected_events,tokens:o.telemetry.used_tokens,recalled:o.telemetry.recall_count>0,evidence:o.telemetry.evidence_verified,robust:o.robust,replayed_decisions:o.replay.decisions.len(),objective}}).collect()}
#[cfg(test)]mod tests{use super::*;#[test]fn ablations_remove_declared_capabilities(){let r=evaluate_modes();let combined=&r[0];assert!(combined.recalled&&combined.evidence&&combined.robust);assert!(!r[1].recalled);assert!(!r[2].evidence);assert!(!r[4].robust);}}
